        let mask_transpiled := sub(0, slt(y_transpiled, 0))
        r_transpiled := xor(
          div(xor(y_transpiled, mask_transpiled), divisor_transpiled),
          mask_transpiled
        )
      }
      let tablePtr := add(table, 1)
      let resultPtr := add(result, 32)

      for {
        let i := 0
      } lt(i, len) {

      } {
